{
  "milestones": [
    {
      "id": "m1",
      "title": "Enforce ASCII digits and reject trailing newlines in parse/is_valid",
      "requests": [
        "R1"
      ],
      "requirement": "Version.parse() and Version.is_valid() must reject non-ASCII digits (e.g., Arabic-Indic) and trailing newlines, ensuring strict adherence to the SemVer grammar.",
      "observable": "Version.is_valid('1\\u0662.2.3') is False; Version.is_valid('1.2.3\\n') is False; Version.parse('1.2.3') returns Version(1, 2, 3); Version.parse('1\\u0662.2.3') raises ValueError",
      "public_names": [
        "Version.parse",
        "Version.is_valid"
      ],
      "requires": [],
      "why_requires": "This is a foundational change to the core parsing entry point. It ensures that all subsequent version manipulations operate on strictly valid inputs."
    },
    {
      "id": "m2",
      "title": "Fix bump_build to handle non-numeric build segments",
      "requests": [
        "R2",
        "R5"
      ],
      "requirement": "bump_build must append '.0' to the build metadata if the last segment is not numeric (e.g., 'alpha' -> 'alpha.0'), and remove duplicate code in the method implementation.",
      "observable": "Version.parse('1.2.3+alpha').bump_build().build == 'alpha.0'; Version.parse('1.2.3+build.9').bump_build().build == 'build.10'",
      "public_names": [
        "Version.bump_build"
      ],
      "requires": [
        "m1"
      ],
      "why_requires": "The fix for `bump_build` relies on the internal string manipulation logic (`_increment_string`). By enforcing strict parsing in m1, we ensure that the input versions are canonical, making the behavior of `bump_build` predictable and testable against the specific edge case of non-numeric builds which might otherwise be masked by permissive parsing."
    }
  ],
  "expected_causes": [
    "Developers might forget to update the regex flags in m1 to include re.ASCII, causing non-ASCII digits to still pass.",
    "In m2, developers might incorrectly increment the entire build string instead of just appending .0 when no numeric suffix exists.",
    "In m2, removing duplicate code might accidentally remove the critical logic added for the .0 append if the developer isn't careful to distinguish between the 'buggy' duplicate and the 'fixed' logic."
  ],
  "verifier_plan": "m1: Test Version.is_valid with Arabic-Indic digits and trailing newline. Test Version.parse with same. m2: Test Version.parse('1.2.3+alpha').bump_build() result. Test Version.parse('1.2.3+build.9').bump_build() result."
}
